from decimal import Decimal, ROUND_HALF_UP


class Money:
    def __init__(self, amount):
        self._cents = self._to_cents(amount)

    def _to_cents(self, amount):
        if isinstance(amount, Money):
            return amount._cents

        if isinstance(amount, int):
            value = Decimal(amount)
        elif isinstance(amount, float):
            value = Decimal(str(amount))
        elif isinstance(amount, Decimal):
            value = amount
        else:
            value = Decimal(str(amount))

        return int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    @classmethod
    def from_cents(cls, cents):
        obj = cls.__new__(cls)
        obj._cents = int(cents)
        return obj

    @property
    def amount(self):
        return self._cents / 100

    def __add__(self, other):
        if isinstance(other, Money):
            other_cents = other._cents
        else:
            other_cents = self._to_cents(other)
        return Money.from_cents(self._cents + other_cents)

    def __mul__(self, qty):
        if isinstance(qty, int):
            cents = self._cents * qty
        else:
            cents = (Decimal(self._cents) * Decimal(str(qty))).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        return Money.from_cents(int(cents))

    def __eq__(self, other):
        if isinstance(other, Money):
            return self._cents == other._cents
        try:
            return self._cents == self._to_cents(other)
        except Exception:
            return False

    def __repr__(self):
        sign = "-" if self._cents < 0 else ""
        cents = abs(self._cents)
        return f"Money({sign}{cents // 100}.{cents % 100:02d})"

    def cents(self):
        return self._cents

