import os
from urllib.parse import unquote


def safe_join(base, user_path):
    try:
        decoded = unquote(user_path)
    except Exception:
        raise ValueError("invalid user_path")

    if "\x00" in decoded:
        raise ValueError("NUL byte in path")

    if decoded.startswith(("/", "\\")) or os.path.isabs(decoded):
        raise ValueError("absolute path")

    if (
        len(decoded) >= 3
        and decoded[0].isalpha()
        and decoded[1] == ":"
        and decoded[2] in ("/", "\\")
    ):
        raise ValueError("absolute path")

    normalized = decoded.replace("\\", "/")

    try:
        base_resolved = os.path.realpath(base)
        candidate = os.path.join(base, normalized)
        resolved = os.path.realpath(candidate)
    except Exception:
        raise ValueError("path could not be resolved")

    if resolved == base_resolved:
        return resolved

    if base_resolved == os.sep:
        return resolved

    if not resolved.startswith(base_resolved + os.sep):
        raise ValueError("path escapes base")

    return resolved

