from fractions import Fraction


class Money:
    def __init__(self, amount):
        self._cents = self._to_cents(amount)

    def _to_cents(self, amount):
        if isinstance(amount, Money):
            return amount._cents

        if isinstance(amount, int):
            return amount * 100

        value = Fraction(str(amount))
        cents = value * 100

        if cents.denominator == 1:
            return int(cents)

        return self._round_half_up(cents)

    @staticmethod
    def _round_half_up(value):
        if value >= 0:
            return int((value + Fraction(1, 2)).numerator // value.denominator)
        return -int((-value + Fraction(1, 2)).numerator // value.denominator)

    def __add__(self, other):
        if not isinstance(other, Money):
            other = Money(other)
        return Money.from_cents(self._cents + other._cents)

    def __mul__(self, qty):
        if isinstance(qty, Money):
            qty = qty._cents
        return Money.from_cents(self._cents * int(qty))

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._cents == other._cents

    def __repr__(self):
        sign = "-" if self._cents < 0 else ""
        abs_cents = abs(self._cents)
        return f"Money({sign}{abs_cents // 100}.{abs_cents % 100:02d})"

    def cents(self):
        return self._cents

    @classmethod
    def from_cents(cls, cents):
        money = cls(0)
        money._cents = int(cents)
        return money

