import os
from urllib.parse import unquote


def safe_join(base, user_path):
    if not isinstance(user_path, str):
        raise ValueError("user_path must be a string")

    decoded = unquote(user_path)

    if "\x00" in decoded:
        raise ValueError("NUL byte in path")

    normalized = decoded.replace("\\", "/")

    if normalized.startswith("/") or normalized.startswith("\\"):
        raise ValueError("absolute path")

    if os.path.isabs(normalized):
        raise ValueError("absolute path")

    if len(normalized) >= 2 and normalized[1] == ":" and normalized[0].isalpha():
        raise ValueError("absolute path")

    base_real = os.path.realpath(base)
    candidate = os.path.join(base_real, normalized)
    resolved = os.path.realpath(candidate)

    if resolved == base_real:
        return resolved

    base_prefix = base_real if base_real.endswith(os.sep) else base_real + os.sep
    if resolved.startswith(base_prefix):
        return resolved

    raise ValueError("path escapes base")

