import sqlite3


def init_v1(conn):
    conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT)")
    conn.execute("CREATE TABLE schema_version (version INTEGER)")
    conn.execute("INSERT INTO schema_version VALUES (1)")
    conn.commit()


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def migrate(conn):
    try:
        schema_rows = conn.execute("SELECT version FROM schema_version").fetchall()
    except sqlite3.Error:
        schema_rows = []

    current_version = schema_rows[0][0] if schema_rows else None

    try:
        conn.execute("SELECT email_domain FROM users LIMIT 0")
        has_email_domain = True
    except sqlite3.Error:
        has_email_domain = False

    if current_version == 2 and has_email_domain and len(schema_rows) == 1:
        return

    try:
        conn.execute("SELECT * FROM users LIMIT 0")
    except sqlite3.Error:
        conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT, email_domain TEXT)")
    else:
        if not has_email_domain:
            conn.execute("ALTER TABLE users ADD COLUMN email_domain TEXT")

    try:
        rows = conn.execute("SELECT id, email, rowid FROM users").fetchall()
    except sqlite3.Error:
        rows = []

    for _, email, row_id in rows:
        if email is None:
            domain = None
        else:
            email_text = str(email)
            if "@" in email_text:
                domain = email_text.rsplit("@", 1)[1].lower()
            else:
                domain = None

        conn.execute("UPDATE users SET email_domain = ? WHERE rowid = ?", (domain, row_id))

    try:
        conn.execute("SELECT version FROM schema_version LIMIT 0")
    except sqlite3.Error:
        conn.execute("CREATE TABLE schema_version (version INTEGER)")

    conn.execute("DELETE FROM schema_version")
    conn.execute("INSERT INTO schema_version VALUES (2)")
    conn.commit()

